"""Billing for visits. Rate lookups are billed, so the charge is remembered."""
import rates


class VisitBill:
    def __init__(self):
        self._visits = []
        self._charge = None

    def add(self, visit):
        """Add one visit to the bill."""
        self._visits.append(visit)

    def charge(self):
        """Return the total charge: minutes times the rate for each visit's page.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.minutes * rates.rate_for(x.page) for x in self._visits)
        return self._charge


def page_names(visits):
    """Return the distinct page values, in first-seen order."""
    names = []
    for x in visits:
        if x.page not in names:
            names.append(x.page)
    return names


def describe_visit(visit):
    """Return a one-line description of a visit."""
    return "%s: %s" % (visit.page, visit.minutes)

